public static void main(String[] args) {
    var sc = new Scanner(System.in);
    int n = sc.nextInt();
    int t = sc.nextInt();
    var hori = new int[n];
    var vert = new int[n];
    int slash = 0;
    int backs = 0;
    for (int x = 1; x <= t; x++) {
        int m = sc.nextInt();
        int i = (m - 1) / n;
        int j = (m - 1) % n;
        hori[i]++;
        vert[j]++;
        if (i == j) {
            backs++;
        }
        if (i + j == n - 1) {
            slash++;
        }
        if (hori[i] == n || vert[j] == n || slash == n || backs == n) {
            System.out.println(x);
            sc.close();
            System.exit(0);
        }
    }
    System.out.println(-1);
    sc.close();
}
